actions.script:
const escape = (text) => String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
const text = String(body || '').trim()
if (!text) { ec.message.addError(ec.l10n.localize('Write the note first')); return }
const html = text.split(/\n{2,}/).map((part) => '<p>' + escape(part).replace(/\n/g, '<br>') + '</p>').join('')
const record = ec.service.sync().name('ironstone.shared.ChatterServices.get#RecordInfo').parameters({recordEntityName: recordEntity || '',
    recordId: recordId || ''}).call()
const out = ec.service.sync().name('ironstone.shared.ChatterServices.log#Note').parameters({recordEntityName: recordEntity, recordId: recordId,
    body: html, recordUrl: record?.url || null}).call()
if (!ec.message.hasError() && out?.message) ec.message.addMessage(out.message, 'success')

const escape = (text) => String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
const text = String(body || '').trim()
if (!text) { ec.message.addError(ec.l10n.localize('Write the message first')); return }
const html = text.split(/\n{2,}/).map((part) => '<p>' + escape(part).replace(/\n/g, '<br>') + '</p>').join('')
const out = ec.service.sync().name('ironstone.client.ClientServices.send#ChatterMessage').parameters({recordEntityName: recordEntity || '',
    recordId: recordId || '', body: html}).call()
if (!ec.message.hasError() && out?.message) ec.message.addMessage(out.message, 'success')

const L = (text) => ec.l10n.localize(text)
// the text of the safe HTML of an entry: paragraphs and breaks as lines, the tags dropped, the entities read
const textOf = (html) => String(html || '').replace(/<br\s*\/?>/gi, '\n').replace(/<\/(p|div|li|h[1-6]|blockquote)>/gi, '\n')
        .replace(/<[^>]*>/g, '').replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
        .replace(/&#39;/g, "'").replace(/&amp;/g, '&').replace(/\n{3,}/g, '\n\n').trim()
asked = !!(recordEntity && recordId)
visible = false
recordTitle = ''
canMessage = false
forClient = false
entryList = []
hasMore = false
if (asked) {
    const data = ec.service.sync().name('ironstone.shared.ChatterServices.get#ChatterData').parameters({recordEntityName: recordEntity, recordId: recordId}).call()
    visible = !ec.message.hasError() && data.visible === true
    // a confidential case's notes and files reach no model (impl-people P21 review, PE-21): an agent's render of this
    // panel (Assist's screen session, the data tool) is told it is not available, as its RequestDetail's opted-out section
    if (visible && sri.isAgentRender()) {
        let entityName = ''
        try { entityName = ec.entity.makeValue(String(recordEntity)).getEntityName() } catch (error) { entityName = '' }
        if (entityName === 'mantle.request.Request' && ec.resource.script('component://mr-mantle/service/mantle/request/PeopleCases.js')
                .isCase(String(recordId))) visible = false
    }
    if (visible) {
        recordTitle = [data.record?.typeLabel, data.record?.title].filter((part) => part).join(': ')
        canMessage = data.canMessage === true
        forClient = data.forClient === true
        const out = ec.service.sync().name('ironstone.shared.ChatterServices.get#Timeline').parameters({recordEntityName: recordEntity,
            recordId: recordId, kinds: 'all'}).call()
        if (!ec.message.hasError()) {
            hasMore = out.hasMore === true
            entryList = Array.from(out.entryList || []).map((entry) => ({dateText: entry.dateFull || entry.dateText || '',
                authorName: entry.authorName || '', whatText: [entry.kindLabel, entry.title].filter((part) => part).join(': ')
                    + (entry.edited ? ' (' + L('edited') + ')' : ''),
                bodyText: textOf(entry.bodyHtml)}))
        }
    }
}
